function modal(id,kicker,title,html){designUI?.close();const changed=currentPanel!==id;closeDaybook();dropModel();currentPanel=id;$('#panel').dataset.page=id;let back=$('#panel-back');if(back)back.hidden=['room','journal','calendar','settings','radio','garden','bookshelf'].includes(id);$('#panel').classList.toggle('model-panel',['fridge','cook','table'].includes(id));$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;if(!$('#panel').open)$('#panel').showModal();if(changed){$('#panel').scrollTop=0;$('#panel-body').scrollTop=0}}
