function table(live=false){if(live!==true){enter();discover(state.worlds[world].meals)};const all=state.worlds[world].meals;const selectedIndex=all.findIndex(i=>i.id===selectedMeal);if(selectedIndex>=0)mealPage=Math.floor(selectedIndex/6);mealPage=Math.max(0,Math.min(mealPage,Math.ceil(all.length/6)-1));const items=all.slice(mealPage*6,mealPage*6+6);if(!items.some(i=>i.id===selectedMeal))selectedMeal=items[0]?.id||null;modal('table','','餐桌','<div id="model-stage" class="table-stage" aria-label="可点选饭菜的三维餐桌"></div>'+(items.length>1?'<details class="recipe-ingredients"><summary>选一道菜</summary><div class="model-picks">'+items.map(i=>'<button data-do="select-meal" data-id="'+i.id+'">'+recipes[i.recipe].name+'</button>').join('')+'</div></details>':'')+'<div id="model-selection"></div><div class="form-actions">'+btn('cook','做饭')+btn('vase','插花')+(mealPage>0?btn('meal-prev','‹',false,'aria-label="上一桌"'):'')+((mealPage+1)*6<all.length?btn('meal-next','›',false,'aria-label="下一桌"'):'')+'</div>');modelView=createModelView($('#model-stage'),{mode:'table',vase:state.worlds[world].life?.vase||[],onVase:()=>lifeUI.show('vase'),items:items.map(i=>({...i,locked:!mealAvailable(i)})),onSelect:i=>selectMeal(i.id)});selectMeal(selectedMeal)}
function mealAvailable(m){const e=findRecord(m.event);return !e?.pending||e.target===actor}
function selectMeal(id){selectedMeal=id;const m=state.worlds[world].meals.find(i=>i.id===id);if(!m){$('#model-selection').innerHTML='<p class="subtle">还没开饭</p>';return}modelView?.select(id);const e=findRecord(m.event);$('#model-selection').innerHTML='<div class="selected-food"><div><b>'+recipes[m.recipe].name+'</b>'+((e?.body&&e.body!=='一顿热乎乎的饭，慢慢吃。')?'<details class="recipe-ingredients"><summary>留言</summary><p>'+esc(e.body)+'</p></details>':'')+'</div>'+(mealAvailable(m)?btn('eat-meal-model','吃饭',true,'data-id="'+id+'"'):'<span class="subtle">保温中 · 留给'+names[m.owner]+'</span>')+'</div>'}


function listRecords(){if(journalTab==='dates')return state.notes.filter(n=>n.kind==='anniversary'&&(n.actor===actor||n.shared)).sort((a,b)=>a.date.localeCompare(b.date));return [...state.events.filter(e=>visible(e,journalTab==='shared')),...state.notes.filter(n=>(n.kind==='memory'||journalTab==='favorites')&&(journalTab==='shared'?n.shared:n.actor===actor||n.shared))].filter(e=>journalTab!=='favorites'||state.favorites[actor].includes(e.id)).sort((a,b)=>b.created-a.created)}
function card(e){return '<article class="memory"><div class="meta"><span>'+(e.kind==='anniversary'?'◷ 纪念日':e.kind==='calendar'?'日历记事':e.shared?'♡ 共同记忆':'✎ 个人生活')+(e.pending?' · 等对方发现':'')+'</span><span>'+esc(e.date||time(e.created))+'</span></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.body)+'</p>'+(e.steps||[]).map(s=>'<div class="reply">'+esc(s.text)+' <span class="subtle">'+time(s.at)+'</span></div>').join('')+(e.comments||[]).map(c=>'<div class="reply"><b>'+names[c.actor]+'</b>：'+esc(c.text)+'</div>').join('')+'<div class="foot">'+planets[e.world]+' · '+esc(e.weather||'手动记录')+(e.repeat?' · 每年纪念':'')+'</div><div class="inline-actions"><button data-do="favorite" data-id="'+e.id+'">'+(state.favorites[actor].includes(e.id)?'★ 已珍藏':'☆ 珍藏')+'</button><button data-do="reply" data-id="'+e.id+'">添一句话</button>'+(e.actor===actor&&!e.shared?'<button data-do="share" data-id="'+e.id+'">放入共同回忆册</button>':'')+(e.actor===actor?'<button data-do="delete" data-id="'+e.id+'">删除</button>':'')+'</div></article>'}
function journal(tab=journalTab){journalTab=tab;const list=listRecords();modal('journal','OUR LITTLE MEMORIES',tab==='shared'?'我们的共同回忆册':names[actor]+'的生活手账','<div class="chips">'+[['personal','我的足迹'],['shared','共同回忆'],['favorites','珍藏']].map(([id,n])=>'<button data-do="journal-tab" data-id="'+id+'" class="'+(id===tab?'active':'')+'">'+n+'</button>').join('')+'</div><div class="inline-actions">'+btn('write','＋ 写一页',true)+btn('calendar','日历')+'<details><summary>更多</summary>'+btn('export','导出记录')+'</details>'+'</div><div id="memories">'+(list.map(card).join('')||'<div class="empty" style="margin-top:18px"><img src="journal-cover.png" alt="星球回忆插画">这里还没有记录。去做一件小事，或亲手写一页吧。</div>')+'</div>')}
function write(kind='memory'){modal('write','A PAGE FOR TODAY',kind==='anniversary'?'把重要的日子记下来':'写下此刻的心情','<form id="note-form"><input type="hidden" name="kind" value="'+kind+'"><div class="form-row"><label for="note-title">'+(kind==='anniversary'?'纪念日名称':'这一页的名字')+'</label><input id="note-title" name="title" required maxlength="80" placeholder="'+(kind==='anniversary'?'第一次见面的日子':'今天的一点小幸福')+'"></div><div class="form-row"><label for="note-body">想留下的话</label><textarea id="note-body" name="body" maxlength="2000" placeholder="为自己做了什么？为对方准备了什么？一起经历了什么？"></textarea></div><div class="grid"><div class="form-row"><label for="note-date">日期</label><input type="date" id="note-date" name="date" value="'+today()+'" required></div><div class="form-row"><label for="note-visibility">收在哪里</label><select id="note-visibility" name="visibility"><option value="private">自己的私人手账</option><option value="shared" '+(cloud&&!cloud.paired?'disabled':journalTab==='shared'?'selected':'')+'>两个人的共同回忆册</option></select></div></div>'+(cloud&&!cloud.paired?'<p class="subtle">尚未配对，先收进自己的手账。配对后可从手账中分享。</p>':'')+'<p id="note-error" class="media-error" role="alert"></p>'+(kind==='anniversary'?'<label class="subtle"><input name="repeat" type="checkbox" checked style="width:auto"> 每年提醒</label>':'')+'<div class="form-actions"><button type="submit" class="pill primary">收进手账</button></div></form>')}
function decorate(){modal('decorate','MAKE IT YOURS','让家，多一点你的样子','<p class="subtle">'+(world===actor?'给院子放一盆小花，装扮会留在自己的星球上。':'正在对方家做客，装扮需要回到自己的星球。')+'</p><div class="item" style="margin-top:18px"><span class="emoji">🌼</span><b>窗前的金色小花</b><small>一小盆，也能让家变温暖。</small>'+(world===actor?btn('flower',state.worlds[world].deco?'收起花盆':'摆进院子',true):btn('go-own','回自己的星球',true))+'</div>')}
let audio=null,timer=null,musicOn=false;
function stopMusic(){clearInterval(timer);audio?.close();audio=null;musicOn=false}
function playMusic(){if(musicOn){stopMusic();music();return}try{audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();musicOn=true;const tones=[261.63,329.63,392,523.25,440,392,329.63,293.66];let n=0;const tick=()=>{if(!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=tones[n++%tones.length];g.gain.setValueAtTime(0,audio.currentTime);g.gain.linearRampToValueAtTime(.05,audio.currentTime+.03);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.8);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+2)};tick();timer=setInterval(tick,700);music()}catch{toast('当前浏览器暂时不能播放声音。')}}
function music(){enter();modal('music','A QUIET AFTERNOON','给房间放一点音乐','<div class="item" style="text-align:center"><span class="emoji">♫</span><b>窗边的小小旋律</b><small>一段轻轻循环的合成音符</small>'+(musicOn?'<div class="music-bars"><i></i><i></i><i></i><i></i><i></i></div>':'')+btn('play-music',musicOn?'暂停音乐':'播放音乐',true)+'</div><p class="subtle" style="margin-top:15px">音乐只在当前设备播放，可以随时暂停。</p>')}
function newGame(){let cards=['🍓','🌼','🍮','🌙','🍓','🌼','🍮','🌙'];for(let i=cards.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}game={cards,open:[],matched:[],moves:0,locked:!mealAvailable(i),done:false}}
function games(){enter();if(!game)newGame();modal('games','PLAY A LITTLE','茶几上的翻牌游戏','<p class="subtle">找出四组相同的小物件。</p><p class="subtle" style="margin:12px 0">已尝试 '+game.moves+' 次 · 找到 '+game.matched.length/2+'/4 组</p><div class="match-grid">'+game.cards.map((c,i)=>'<button data-do="flip" data-id="'+i+'" aria-label="第 '+(i+1)+' 张牌" class="'+(game.matched.includes(i)?'matched':'')+'" '+(game.locked||game.matched.includes(i)?'disabled':'')+'>'+(game.open.includes(i)||game.matched.includes(i)?c:'✳')+'</button>').join('')+'</div><div class="form-actions">'+btn('new-game','重新洗牌')+'</div>')}
function settings(){if(cloud)return cloudSettings();modal('settings','PLAYABLE PROTOTYPE','在两个人的生活间切换','<p class="subtle">当前是'+names[actor]+'的视角。切换角色后，可以发现另一位留下的饭和零食，查看各自的手账。</p><div class="chips">'+names.map((n,i)=>'<button data-do="switch-actor" data-id="'+i+'" class="'+(i===actor?'active':'')+'">'+n+' · '+planets[i]+'</button>').join('')+'</div><div class="preview-info">这是单设备交互原型：两位角色、城市与天气为演示，尚未接入真实定位、天气接口、账号或跨设备联机。记录保存在当前浏览器；私人手账的分隔用于演示，不构成真实账号权限。音乐是本地生成的简短旋律。</div><div class="form-actions">'+btn('export-all','导出当前角色全部手账')+'</div>')}
function findRecord(id){return state.events.find(e=>e.id===id)||state.notes.find(e=>e.id===id)}
function reply(id){const e=findRecord(id);if(!e)return;modal('reply','ADD YOUR WORDS','在回忆旁，添一句话','<p class="subtle">'+esc(e.title)+'</p><form id="reply-form" data-id="'+id+'"><div class="form-row"><label for="reply-text">'+names[actor]+'想说</label><textarea id="reply-text" name="text" required maxlength="500"></textarea></div><div class="form-actions"><button type="submit" class="pill primary">留下这句话</button></div></form>')}
function exportRecords(all=false){const list=all?[...state.events.filter(e=>visible(e)),...state.notes.filter(e=>e.actor===actor||e.shared)]:listRecords();const text='# '+names[actor]+'的生活手账\n\n'+list.map(e=>'## '+e.title+'\n'+(e.date||time(e.created))+' · '+planets[e.world]+'\n\n'+e.body+'\n'+(e.steps||[]).map(s=>s.text).join('\n')+'\n'+(e.comments||[]).map(c=>names[c.actor]+'：'+c.text).join('\n')+'\n').join('\n---\n\n');const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=names[actor]+'的生活手账-'+today()+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('手账已导出为文字文件。')}
function roomMenu(){enter();const group=(title,rows)=>'<section class="room-group"><h3>'+title+'</h3><div class="room-list">'+rows.map(([a,i,t])=>'<button data-do="'+a+'"><span>'+i+'</span><small>'+t+'</small></button>').join('')+'</div></section>';modal('room','','房间',group('一层 · 客厅',[['sit','▤','沙发'],['fridge','♧','冰箱'],['cook','♨','厨房'],['table','◯','餐桌'],['bookshelf','▥','书架'],['journal','▤','手账'],['music','♫','唱片机'],['vase','✿','花瓶'],['games','✳','小游戏']])+group('二层 · 卧室',[['bed','☾','床'],['bathroom','♧','洗手间'],['wardrobe','♢','衣柜'],['desk-0','▱','座椅'],['travel','◇','旅行箱']]))}

function hideBasketballPrompt(){if(!$('#confirm-basketball'))return;dock('');$('.scene-wrap').classList.remove('engaged')}
$('.scene-wrap').addEventListener('pointerdown',e=>{if(e.target.tagName==='CANVAS')hideBasketballPrompt()});
function act(a){hideBasketballPrompt();if(a==='lighting'){lightUI.open();return}if(a==='seat-occupied'){toast('对方正坐在这里，换个位置吧');return}if(a==='peer'){if(!visual?.nearPeer()){toast('靠近一点，等对方空下来再互动吧');return}openPeerActions();return}if(a==='go-basketball'){if(travelUI?.away)return;close();dock('<button id="confirm-basketball">去打篮球</button>');$('#confirm-basketball').onclick=()=>requestAction('basketball');return}if(travelUI?.away&&!['mailbox','travel','activity-ended'].includes(a)){toast('小熊正在旅行，去信箱看看吧');return}if(a==='travel'){travelUI?.suitcase();return}if(a==='mailbox'){travelUI?.mailbox();return}if(!/^sit(?:-|$)/.test(a))wordCards.close();if(a==='sleep-options'){sleepSound.reopen();return}if(a==='hammock-options'){dock('<button data-outdoor=drink>来瓶饮料？</button>');return}if(a==='hammock'){startSunbathing();return}if(a==='reading-book'){mediaUI.openReading();return}if(mediaUI.show(a))return;if(lifeUI.show(a))return;if(a==='stairs'){visual?.climb();return}if(a==='bed'){bedroom();return}if(a==='puppy'){showPet();return}if(a.startsWith('pet-')){petCompleted(a);return}if(a==='activity-ended'){endOutdoor();return}if(a==='camp'){campSite();return}if(a==='sit'&&!inside){readBench();return}if(a==='walk-complete'){record(names[actor]+'绕着'+planets[world]+'散步了一圈','走过树林、菜园和小屋，又回到熟悉的地方。',{target:world,shared:world!==actor});toast('散步一圈的记忆，已经收进手账。');return}if(a==='home'){enter();return}({fridge,cook:kitchen,table,journal,bag,decorate,music,games,settings,room:roomMenu})[a]?.();if(/^sit(?:-|$)/.test(a)&&inside){travelUI?.sofa(a)}if(a==='pet')toast('小兔子抬起头，轻轻蹭了蹭你的手。')}
const handlers={travel:()=>{close();visual?.request('travel')},sit:()=>{close();visual?.request('sit')},fridge,bag,cook:kitchen,table,music,games,write:()=>write(),anniversary:()=>calendarUI?.open(),'go-own':()=>go(actor),'play-music':playMusic,export:()=>exportRecords(),'export-all':()=>exportRecords(true),'eat-fridge'(b){let i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id);if(!i||i.qty<=0||foodCatalog[i.food]?.ready===false)return;let e=state.events.find(e=>e.id===i.event);if(e?.pending&&e.target!==actor)return;i.qty--;if(e)e.steps.push({text:names[actor]+'吃了'+foods[i.food][0]+'。',at:Date.now()});else record(names[actor]+'吃了一份'+foods[i.food][0],'照顾好自己，也是一件值得记下的小事。');state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);save();fridge();toast('慢慢吃，好好享受这一口。')}, 'eat-meal':async function(b){const item=b.dataset.id;try{if(cloud){if(!await cloud.life({type:'shared-meal-eat',world,item}))return}else{const next=structuredClone(state);applyLife(next,actor,true,{type:'shared-meal-eat',world,item},Date.now(),uid);state=next;save()}refresh();table()}catch(e){toast(e.message)}},'journal-tab'(b){journal(b.dataset.id)},favorite(b){let a=state.favorites[actor];state.favorites[actor]=a.includes(b.dataset.id)?a.filter(i=>i!==b.dataset.id):[...a,b.dataset.id];save();journal()},reply(b){reply(b.dataset.id)},share(b){if(cloud&&!cloud.paired)return toast('请先与对方配对。');let e=findRecord(b.dataset.id);if(e?.actor===actor){e.shared=true;save();journal();toast('已经放入共同回忆册。')}},delete(b){let e=findRecord(b.dataset.id);if(e?.actor!==actor)return;modal('delete','KEEP OR LET GO','删除这条记录？','<p class="subtle">'+esc(e.title)+'<br>删除后将从相关手账中移除。云端版需先吃完关联食物，再删除对应记录。</p><div class="form-actions">'+btn('cancel-delete','保留')+btn('confirm-delete','删除记录',false,'data-id="'+e.id+'"')+'</div>')},'cancel-delete':()=>journal(),'confirm-delete'(b){const id=b.dataset.id;if(cloud&&state.worlds.some(w=>[...w.fridge,...w.meals].some(i=>i.event===id)))return toast('这条记录关联的食物还在，请吃完后再删除。');state.events=state.events.filter(e=>e.id!==id||e.actor!==actor);state.notes=state.notes.filter(e=>e.id!==id||e.actor!==actor);save();journal()},flower(){if(world!==actor)return;let w=state.worlds[world];w.deco=!w.deco;visual?.decorate(w.deco);if(w.deco)record(names[actor]+'在院子里摆了一盆小花','给自己的家，添一点暖黄色。');save();decorate()},'switch-actor'(b){if(cloud)return;let n=Number(b.dataset.id);if(n!==0&&n!==1)return;actor=n;save();go(actor);toast('现在是'+names[actor]+'的视角。')},'new-game'(){newGame();games()},flip(b){if(!game||game.locked)return;let i=Number(b.dataset.id);if(game.open.includes(i)||game.matched.includes(i))return;game.open.push(i);if(game.open.length===2){game.moves++;if(game.cards[game.open[0]]===game.cards[game.open[1]]){game.matched.push(...game.open);game.open=[];if(game.matched.length===8&&!game.done){game.done=true;record(names[actor]+'完成了茶几上的翻牌游戏','用了'+game.moves+'次尝试，找到了四组小物件。');toast('都找到了！这个小成就已经记进手账。')}}else{game.locked=true;let g=game;setTimeout(()=>{if(g!==game)return;game.open=[];game.locked=false;if(currentPanel==='games')games()},850)}}games()}};
$('#panel-body').addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(b&&!b.disabled){if(travelUI?.away&&['sit','fridge','cook','table','bookshelf','games','vase','bathroom','wardrobe','bed','stairs','eat-model','cook-food','sunbathe-drink','sofa-album','sofa-words'].includes(b.dataset.do)){toast('小熊正在旅行，去信箱看看吧');return}if(currentPanel==='room'&&['fridge','cook','table','journal','music','bookshelf','games'].includes(b.dataset.do)){close();visual?.request(b.dataset.do)}else handlers[b.dataset.do]?.(b)}});
$('#panel-body').addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.target);if(e.target.id==='note-form'){let title=String(d.get('title')||'').trim();if(!title)return;let date=String(d.get('date'));if(cloud&&!cloud.paired&&d.get('visibility')==='shared'){$('#note-error').textContent='请先配对，或选择自己的私人手账。内容尚未保存。';return;}state.notes.unshift({id:uid(),actor,world,title,body:String(d.get('body')||'').trim(),date,kind:d.get('kind'),shared:d.get('visibility')==='shared',repeat:d.has('repeat'),created:Date.now(),weather:date===today()?weatherStamp():'',comments:[]});save();journal(d.get('kind')==='anniversary'?'dates':d.get('visibility')==='shared'?'shared':'personal');toast('这一页，已经好好收起来了。')}else if(e.target.id==='reply-form'){let r=findRecord(e.target.dataset.id),text=String(d.get('text')||'').trim();if(r&&text){r.comments??=[];r.comments.push({actor,text,at:Date.now()});save();journal();toast('回忆里，多了你的一句话。')}}});
$('#close-panel').onclick=close;$('#panel').addEventListener('close',()=>{if(!$('#panel').open){dropModel();currentPanel=''}});$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){let r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
$('#enter-home').onclick=()=>{endOutdoor();if(inside){inside=false;visual?.enter(false);refresh()}else visual?.request('home')};$('.brand').onclick=e=>{e.preventDefault();go(actor)};$('#settings').onclick=settings;$('#identity').onclick=settings;$('#partner-peek').onclick=()=>go(1-world);$('#zoom-in').onclick=()=>visual?.zoom(.12);$('#zoom-out').onclick=()=>visual?.zoom(-.12);$('#all-memories').onclick=()=>journal();$$('[data-world]').forEach(b=>b.onclick=()=>go(b.dataset.world==='0'?actor:1-actor));$$('[data-action]').forEach(b=>b.onclick=()=>requestAction(b.dataset.action));$$('[data-weather]').forEach(b=>b.onclick=async()=>{if(cloud&&world!==actor)return toast('天气由这颗星球的主人设置。');if(environment&&!(await environment.manual()))return;state.worlds[world].weather=b.dataset.weather;save();refresh()});$$('[data-nav]').forEach(b=>b.onclick=()=>{let a=b.dataset.nav;if(a==='planet'){endOutdoor();inside=false;visual?.enter(false);refresh()}else if(a==='home'){close();closeDaybook();endOutdoor();if(inside){inside=false;visual?.enter(false);refresh()}else visual?.request('home');}else act(a)});
