$('#activity-dock').addEventListener('click',e=>{if(e.target.closest('[data-pet]'))return;const b=e.target.closest('[data-outdoor]');if(!b)return;const a=b.dataset.outdoor;if(a==='leave')return endOutdoor();if(a==='drink')return hammockPicker();if(a==='page'){if(visual?.turnPage()===false)return;readingPage=(readingPage+1)%3;renderReading();return}if(a==='tent'){if(cloud&&world!==actor)return toast('帐篷由主人搭建，你可以在已有的营地坐坐。');let w=state.worlds[world];w.camp=!w.camp;visual?.camp(w.camp);paired=false;if(w.camp)record(names[actor]+'在'+planets[world]+'搭起了帐篷','放好睡垫，点亮一盏露营灯。',{target:world,shared:world!==actor});save();renderCamp();return}if(a==='rest'){visual?.rest(paired);if(!campEvent)campEvent=record(names[actor]+'在帐篷前坐了一会儿','慢下来，听听周围的风。');renderCamp();return}if(a==='pair'){if(cloud)return toast('对方来到这里并坐下，就能一起待着。');paired=!paired;if(outdoorMode==='read'){visual?.sit(paired,true);if(paired&&readingEvent){readingEvent.shared=true;readingEvent.target=1-actor;readingEvent.title='我们一起在长椅上读书';readingEvent.body='在《风路过的地方》里，读到同一阵晚风。（双人动作演示）';save()}renderReading()}else{visual?.rest(paired);if(paired&&!campEvent)campEvent=record('我们一起在帐篷前露营','毯子上有两个人的位置，灯为我们亮着。（双人动作演示）',{target:1-actor,shared:true});else if(paired&&campEvent){campEvent.shared=true;campEvent.target=1-actor;campEvent.title='我们一起在帐篷前露营';save()}renderCamp()}}});
$('#go-camp').onclick=()=>outdoors('camp');$('#go-read').onclick=()=>outdoorMode==='read'?mediaUI.openReading():outdoors('read');


handlers['meal-prev']=()=>{mealPage--;selectedMeal=null;table()};handlers['meal-next']=()=>{mealPage++;selectedMeal=null;table()};
handlers['cook-food']=b=>{const i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id&&i.qty>0),e=findRecord(i?.event);if(!i||foodCatalog[i.food]?.ready!==false)return;pendingCookSource={id:i.id,world};kitchen()};
handlers['gift-food']=b=>{if(world!==actor||!cloud?.paired)return;const item=state.worlds[actor].fridge.find(i=>i.id===b.dataset.id&&i.qty>0);if(!item)return;const old=findRecord(item.event);if(old?.pending&&old.target!==actor)return;item.qty--;state.worlds[actor].fridge=state.worlds[actor].fridge.filter(i=>i.qty>0);const e=record(names[actor]+'留了一份'+foods[item.food][0],'放在冰箱里，等你回来。',{target:1-actor,shared:true,pending:true});state.worlds[1-actor].fridge.push({id:uid(),food:item.food,qty:1,event:e.id});save();fridge()};
handlers['stock-fridge']=stockFridge;handlers['stock-category']=b=>{stockCategory=b.dataset.category;stockFridge()};handlers['stock-food']=b=>{const f=b.dataset.food;if(world!==actor||!foodCatalog[f])return;let i=state.worlds[world].fridge.find(i=>i.food===f&&!i.event);if(i)i.qty=Math.min(999,i.qty+1);else state.worlds[world].fridge.push({id:uid(),food:f,qty:1});save();toast('已放入'+foods[f][0]);};

handlers['sunbathe-drink']=b=>{const i=state.worlds[world].fridge.find(x=>x.id===b.dataset.id),e=findRecord(i?.event);if(!i||i.qty<=0||!drinkFoods.has(i.food)||e?.pending&&e.target!==actor)return;if(!visual)return toast('3D 场景尚未就绪');endOutdoor();close();inside=false;visual.enter(false);refresh();hammockDrink={id:i.id,world};outdoorMode='hammock-walk';dock('<button data-outdoor="leave">取消</button>');$('#activity-dock').classList.add('hammock-dock');if(visual.request('hammock')===false){endOutdoor();toast('暂时走不到吊床，请再试一次。')}};
function hammockPicker(){
 const choices=state.worlds[world].fridge.filter(i=>i.qty>0&&drinkFoods.has(i.food)&&(!findRecord(i.event)?.pending||findRecord(i.event)?.target===actor));
 if(!choices.length)return toast('冰箱里暂时没有饮料');
 dock('<div class="sleep-wheel-shell"><div class="sleep-wheel-band"></div><div class="sleep-wheel" tabindex="0" role="listbox" aria-label="选择饮料">'+choices.map((i,n)=>'<div role="option" aria-selected="false" data-drink="'+n+'">'+foods[i.food][0]+'</div>').join('')+'</div></div>');
 const wheel=$('#activity-dock .sleep-wheel');let timer,armed=false;
 function choose(){if(!armed||outdoorMode!=='hammock'||!wheel.isConnected)return;armed=false;const n=Math.max(0,Math.min(choices.length-1,Math.round(wheel.scrollTop/48)));hammockDrink={id:choices[n].id,world};startSunbathing()}
 wheel.onpointerdown=()=>armed=true;wheel.onwheel=()=>armed=true;wheel.onscroll=()=>{clearTimeout(timer);if(armed)timer=setTimeout(choose,220)};wheel.onpointerup=()=>{clearTimeout(timer);timer=setTimeout(choose,250)};
 wheel.onclick=e=>{const opt=e.target.closest('[data-drink]');if(!opt)return;armed=true;wheel.scrollTop=Number(opt.dataset.drink)*48;clearTimeout(timer);timer=setTimeout(choose,220)};
 wheel.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Enter'].includes(e.key))return;e.preventDefault();armed=true;if(e.key==='Enter')choose();else{wheel.scrollTop+=e.key==='ArrowUp'?-48:48;clearTimeout(timer);timer=setTimeout(choose,350)}};
}
function startSunbathing(){const choice=hammockDrink;hammockDrink=null;if(!choice){if(!visual?.sunbathe(null)){endOutdoor();return}outdoorMode='hammock';dock('');$('#activity-dock').classList.add('hammock-dock');return}const i=state.worlds[choice.world]?.fridge.find(x=>x.id===choice.id),e=findRecord(i?.event);if(choice.world!==world||!i||i.qty<=0||!drinkFoods.has(i.food)||e?.pending&&e.target!==actor){endOutdoor();return toast('这份饮料已经不在冰箱里了。')}if(!visual?.sunbathe(i.food)){endOutdoor();return}i.qty--;state.worlds[world].fridge=state.worlds[world].fridge.filter(x=>x.qty>0);if(e)e.steps.push({text:names[actor]+'带着'+foods[i.food][0]+'去吊床休息。',at:Date.now()});record(names[actor]+'带着'+foods[i.food][0]+'在吊床上休息','戴上墨镜，轻轻晃一晃，慢慢喝完这份饮料。');save();outdoorMode='hammock';dock('');$('#activity-dock').classList.add('hammock-dock');}

handlers['select-food']=b=>selectFood(b.dataset.id);handlers['select-meal']=b=>selectMeal(b.dataset.id);
for(const [from,to]of [['eat-model','eat-fridge'],['eat-meal-model','eat-meal']])handlers[from]=async b=>{const view=modelView,id=b.dataset.id;if(!view||b.disabled)return;b.disabled=true;await view.consume(id);if(modelView!==view)return;handlers[to]({dataset:{id}})};


function petName(){return (state.worlds[world].theme??world)===0?'饼干':'栗子'}
function showPet(){close();outdoorMode='pet';dock('');$('.scene-wrap').classList.add('pet-active');renderPet()}
function renderPet(){const p=visual?.readState().pet,mode=p?.mode||'idle',busy=['throw','fetch','return','feed-approach','feeding'].includes(mode);dock('<div class="dock-heading"><span>♧ '+petName()+' · '+({walk:'陪你散步',throw:'玩具飞出去啦',fetch:'跑去捡玩具',return:'叼着玩具回来了',feeding:'正在吃饭','feed-approach':'跑向饭碗',home:'回门口休息'}[mode]||'摇着尾巴等你')+'</span><button data-outdoor="leave" aria-label="让小狗回家">×</button></div><div class="dock-actions">'+[['walk',mode==='walk'?'结束散步':'一起散步'],['ball','扔小球'],['disc','扔飞盘'],['feed','喂一碗饭']].map(([id,text])=>'<button data-pet="'+id+'" '+(busy?'disabled':'')+'>'+text+'</button>').join('')+'</div>')}
function petCompleted(action){const w=state.worlds[world];w.pet=w.pet||{feeds:0,games:0,walks:0};if(action==='pet-fed'){w.pet.feeds++;record(names[actor]+'给'+petName()+'喂了饭','小狗低下头，把碗里的饭吃干净了。',{target:world,shared:world!==actor})}else if(action.startsWith('pet-fetch-')){w.pet.games++;record(names[actor]+'和'+petName()+'玩了'+(action.endsWith('disc')?'飞盘':'小球'),'小狗跑过去，叼着玩具回到了身边。',{target:world,shared:world!==actor})}if(outdoorMode==='pet')renderPet()}
$('#go-pet').onclick=()=>{endOutdoor();close();if(inside){inside=false;visual?.enter(false);refresh()}visual?.request('puppy')};
$('#activity-dock').addEventListener('click',e=>{const b=e.target.closest('[data-pet]');if(!b||b.disabled)return;let a=b.dataset.pet;if(a==='walk'&&visual?.readState().pet.mode==='walk'){visual.pet('home');state.worlds[world].pet??={feeds:0,games:0,walks:0};state.worlds[world].pet.walks++;record(names[actor]+'带'+petName()+'出去散步','沿着星球的小路走了一会儿，再回家休息。',{target:world,shared:world!==actor});renderPet();return}if(!visual?.pet(a))return toast('让小狗先把这件事做完吧。');renderPet()});


